    mtr=[("MTR.5.1", "Notes I — the product is regrouped before it is evaluated, so 'multiply the fronts, add the backs' is read off the structure rather than memorised as a rule."),
         ("MTR.3.1", "Boards 1, 3 and 7 — one move each, written and up on the cue; dividing in scientific notation was the lowest single figure on the last state report."),
         ("MTR.4.1", "Board 6 — when the room splits between 2 × 10¹⁰ and 20 × 10⁹, which are the same number, the sixty-second re-vote before the reveal.")],

    hoq=[("Why do the powers of ten have to match before you add, but not before you multiply?", "DOK 3"),
         ("Marcus's power of ten is right and Sara's coefficient is right. Which of the two is closer to the correct answer, and does 'closer' mean anything useful here?", "DOK 3"),
         ("A quotient of two positive numbers comes out as 5.3 × 10⁻³. What does the negative exponent tell you about how the two numbers compared?", "DOK 2")],

    differentiation=dict(
        ese="Give a two-column organiser — COEFFICIENTS on the left, POWERS OF TEN on the right — and have the student split every expression into the two columns before computing anything. The regrouping step in Notes I becomes a physical act, and the two laws are then applied one column at a time.",
        ell="Product and quotient are the two nouns, multiply and divide the two verbs. Write them in pairs on the board — PRODUCT goes with MULTIPLY and ADD the exponents, QUOTIENT goes with DIVIDE and SUBTRACT the exponents — and read each board's operation aloud before the boards go up.",
        enrichment="Ask for (4 × 10⁵)² without a calculator, then for the two numbers whose product is 1.2 × 10⁷ and whose quotient is 3 × 10¹."),

